def solve():
    import sys
    from collections import deque

    data = sys.stdin.read().split("\n")
    r, c = map(int, data[0].split())
    grid = [data[1 + i] for i in range(r)]

    dist = [[-1] * c for _ in range(r)]
    q = deque()
    empty_count = 0
    for i in range(r):
        for j in range(c):
            if grid[i][j] == "*":
                dist[i][j] = 0
                q.append((i, j))
            elif grid[i][j] == ".":
                empty_count += 1

    while q:
        y, x = q.popleft()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < r and 0 <= nx < c and grid[ny][nx] != "#" and dist[ny][nx] == -1:
                dist[ny][nx] = dist[y][x] + 1
                q.append((ny, nx))

    if empty_count == 0:
        print(0)
        return

    max_d = 0
    for i in range(r):
        for j in range(c):
            if grid[i][j] == ".":
                if dist[i][j] == -1:
                    print(-1)
                    return
                max_d = max(max_d, dist[i][j])

    print(max_d)

solve()
